class CacheService:
    def __init__(self):
        self.store = {}
        self.cache = {}

    def write(self, k, v):
        self.store[k] = v
        # Bug: Forgot to invalidate self.cache[k]

    def read(self, k):
        if k in self.cache: return self.cache[k]
        val = self.store.get(k)
        self.cache[k] = val
        return val

