        return {"status": "processed", "new_balance": self.balance}

class Inventory:
    def __init__(self, stock):
        self.stock = stock

    def reserve(self, qty):
        # Non-atomic check-then-decrement
        if self.stock >= qty:
            self.stock -= qty
            return True
        return False

def verify_signature(provided: str, expected: str) -> bool:
